<script setup>
import { ref } from 'vue'
import PsIcon from './PsIcon.vue'
const props = defineProps({ store: Object })
const emit = defineEmits(['close'])
const selected = ref(props.store.state.selectedDeviceId)
const scenarios = [ ['high','高限预警','黄色 · 上限越界','Thermometer','warning'], ['low','低限预警','黄色 · 下限越界','ArrowDownRight','warning'], ['critical','严重超限','红色 · 高高限越界','BellRing','critical'], ['rapidUp','快速上升','红色 · 正斜率过大','TrendingUp','critical'], ['rapidDown','快速下降','红色 · 负斜率过大','Zap','critical'], ['offline','设备离线','连续无数据后预警','WifiOff','warning'] ]
function inject(kind) { props.store.injectScenario(kind, selected.value); emit('close') }
</script>
<template><Teleport to="body"><div class="ps-global-root"><div class="ps-drawer-backdrop" @click.self="emit('close')"><aside class="ps-demo-drawer" role="dialog" aria-modal="true" aria-label="演示控制台" @keydown.esc="emit('close')"><header class="ps-dialog-header"><div><h2><PsIcon name="SlidersHorizontal" :size="20"/>演示控制台</h2><p>注入模拟工况，验证各页面全局预警</p></div><button class="ps-icon-button" aria-label="关闭演示控制台" @click="emit('close')"><PsIcon name="X" :size="22"/></button></header><div class="ps-drawer-body"><label class="ps-field">选择演示设备<select v-model="selected"><option v-for="device in store.state.devices" :key="device.id" :value="device.id">{{ device.name }} · {{ device.metric }}</option></select></label><span class="ps-form-section-label">异常场景</span><div class="ps-scenario-grid"><button v-for="scenario in scenarios" :key="scenario[0]" :class="['ps-scenario', scenario[4]]" @click="inject(scenario[0])"><PsIcon :name="scenario[3]" :size="22"/><b>{{ scenario[1] }}</b><small>{{ scenario[2] }}</small></button></div><div class="ps-demo-explain"><span>01</span><p>选择任意页面并注入异常</p><span>02</span><p>等待持续时间满足，自动弹窗和闪烁边框</p><span>03</span><p>确认告警或转工单，恢复后完成维护验收</p></div><label class="ps-toggle-row"><div><b>自动场景轮播</b><small>每 30 秒切换工况，可跨页面观察</small></div><input v-model="store.state.autoDemo" type="checkbox" role="switch" aria-label="自动场景轮播"/></label><button class="ps-button ps-button-full" @click="store.restoreAll(); emit('close')"><PsIcon name="RefreshCw" :size="17"/>恢复全部演示数据</button><p class="ps-drawer-note">告警确认后仍保留风险提示；工况恢复后自动解除边框。声效需手动启用。</p></div></aside></div></div></Teleport></template>
